text:
Here is the pricing implementation with its embedded stylesheet:

&lt;style&gt;
@import url('<https://fonts.googleapis.com/css2?family=Oswald:wght@500;600&amp;family=Montserrat:wght@500;600;700;800&amp;display=swap>');

.pricing-section{
padding:80px 20px;
background:transparent;
}

.pricing-header{
text-align:center;
margin-bottom:50px;
}

.pricing-header h2{
font-family:'Oswald', sans-serif;
font-size:64px;
color:#111;
margin-bottom:15px;
}

.pricing-header p{
font-family:'Montserrat', sans-serif;
font-size:20px;
color:#555;
max-width:700px;
margin:auto;
line-height:1.6;
}

.pricing-grid{
max-width:1300px;
margin:auto;
display:grid;
grid-template-columns:repeat(3, 1fr);
gap:30px;
}

.pricing-card{
background:#fff;
border:2px solid #e5e5e5;
padding:40px 35px;
text-align:center;
border-radius:16px;
box-shadow:0 8px 30px rgba(0,0,0,0.06);
transition:0.3s ease;
}

.pricing-card:hover{
transform:translateY(-6px);
}

.featured{
border:3px solid #ff6a00;
transform:scale(1.03);
}

.pricing-note{
background:#fff3eb;
color:#ff6a00;
font-family:'Montserrat', sans-serif;
font-size:14px;
font-weight:700;
padding:10px 14px;
border-radius:100px;
display:inline-block;
margin-bottom:25px;
}

.pricing-card h3{
font-family:'Oswald', sans-serif;
font-size:42px;
color:#111;
margin-bottom:15px;
}

.price{
font-family:'Montserrat', sans-serif;
font-size:72px;
font-weight:800;
color:#111;
margin-bottom:30px;
}

.pricing-card ul{
list-style:none;
padding:0;
margin:0 0 35px;
text-align:left;
}

.pricing-card li{
font-family:'Montserrat', sans-serif;
font-size:17px;
color:#444;
margin-bottom:14px;
position:relative;
padding-left:28px;
line-height:1.5;
}

.pricing-card li::before{
content:"✓";
position:absolute;
left:0;
color:#58c11b;
font-weight:800;
}

.pricing-btn{
display:inline-block;
background:#58c11b;
color:#fff;
text-decoration:none;
font-family:'Montserrat', sans-serif;
font-size:17px;
font-weight:700;
padding:18px 34px;
border-radius:10px;
transition:0.3s ease;
}

.pricing-btn:hover{
opacity:0.9;
color:#fff;
}

@media(max-width:991px){
.pricing-grid{
grid-template-columns:1fr;
}

.featured{
transform:none;
}

.pricing-header h2{
font-size:42px;
}

.price{
font-size:54px;
}
}
&lt;/style&gt;

&lt;section class="pricing-section"&gt;
&lt;div class="pricing-header"&gt;
&lt;h2&gt;Choose Your Enrollment Option&lt;/h2&gt;
&lt;p&gt;Select the path that best fits your journey and begin your certification today.&lt;/p&gt;
&lt;/div&gt;

&lt;div class="pricing-grid"&gt;
&lt;!-- PLAN 1 --&gt;
&lt;div class="pricing-card"&gt;
&lt;div class="pricing-note"&gt;Price increases on September 22nd&lt;/div&gt;
&lt;h3&gt;Basic&lt;/h3&gt;
&lt;div class="price"&gt;$1,450&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;Full Radiant Mentor Institute Access&lt;/li&gt;
&lt;li&gt;Core Training Modules&lt;/li&gt;
&lt;li&gt;Private Community Access&lt;/li&gt;
&lt;li&gt;Certification Completion Badge&lt;/li&gt;
&lt;li&gt;Lifetime Course Access&lt;/li&gt;
&lt;/ul&gt;
&lt;a href="<https://radiant-mentor.example/offers/SpringPath4827/checkout>" class="pricing-btn"&gt;Enroll Now&lt;/a&gt;
&lt;/div&gt;

&lt;!-- PLAN 2 --&gt;
&lt;div class="pricing-card featured"&gt;
&lt;div class="pricing-note"&gt;Most Popular Option&lt;/div&gt;
&lt;h3&gt;Professional&lt;/h3&gt;
&lt;div class="price"&gt;$3,250&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;Everything In Basic&lt;/li&gt;
&lt;li&gt;Advanced Coaching Techniques&lt;/li&gt;
&lt;li&gt;Group Workshop Templates&lt;/li&gt;
&lt;li&gt;Bonus Client Resources&lt;/li&gt;
&lt;li&gt;Monthly Live Coaching Calls&lt;/li&gt;
&lt;li&gt;Priority Support&lt;/li&gt;
&lt;/ul&gt;
&lt;a href="<https://radiant-mentor.example/offers/SpringPath4827/checkout>" class="pricing-btn"&gt;Get Started&lt;/a&gt;
&lt;/div&gt;

&lt;!-- PLAN 3 --&gt;
&lt;div class="pricing-card"&gt;
&lt;div class="pricing-note"&gt;Limited VIP Spots Available&lt;/div&gt;
&lt;h3&gt;VIP Elite&lt;/h3&gt;
&lt;div class="price"&gt;$8,750&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;Everything In Professional&lt;/li&gt;
&lt;li&gt;Private 1:1 Mentorship&lt;/li&gt;
&lt;li&gt;VIP Intensive Workshops&lt;/li&gt;
&lt;li&gt;Direct Coaching Feedback&lt;/li&gt;
&lt;li&gt;Exclusive Mastermind Access&lt;/li&gt;
&lt;li&gt;High-Level Business Strategy&lt;/li&gt;
&lt;/ul&gt;
&lt;a href="<https://radiant-mentor.example/offers/SpringPath4827/checkout>" class="pricing-btn"&gt;Apply Now&lt;/a&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/section&gt;
